    <template v-if="localKind&&!localId"><el-input v-model="keyword" aria-label="实际SKU检索文字" placeholder="原目录名称或条码" /><el-button @click="search">查询实际SKU</el-button><el-select :model-value="undefined" aria-label="实际SKU选择" placeholder="明确选择，不自动取第一项" @update:model-value="selectItem"><el-option v-for="s in catalog" :key="s.item_id" :value="s.item_id" :label="s.name+' · #'+s.item_id" /></el-select><el-pagination v-if="catalogTotal>20" v-model:current-page="catalogPage" :page-size="20" :total="catalogTotal" layout="prev,pager,next" @current-change="()=>search(false)" /></template>
    <p v-if="localId">实际{{ localKind==='pharmaceutical'?'药品':'耗材' }}：{{ selectedName||'#'+localId }} · hospital_inventory <el-button v-if="!itemId" @click="selectItem(null)">重新选择SKU</el-button></p>
   </div>
   <div class="toolbar"><el-select v-model="sourceKind" aria-label="库存原件类型" placeholder="明确选择原件类型" clearable><el-option v-for="(label,key) in inventorySourceKinds" :key="key" :value="key" :label="label" /></el-select><el-button :loading="loading" @click="reload">刷新库存原件目录</el-button><el-button v-if="localId&&options?.can_record" :disabled="!sourceKind||loading||saving" @click="openCreate">登记本类待审核原件</el-button><el-button v-if="localId" @click="unitDialog=true">管理实际原计数单位</el-button></div>
