    <InventorySourceEditor v-model="form" :kind="sourceKind" :units="units" :selected-unit="selectedUnit" :can-confirm-professional="options?.can_confirm_professional===true" :professional-signer-user-id="options?.professional_signer_user_id??null" @unit-change="chooseUnit" />
    <template v-if="sourceKind==='inventory_observation'"><el-button :loading="rawLoading" @click="readRaw">读取本实际SKU完整原库存胶囊</el-button><p>技术采集时刻不是物理观察时刻。仅安全字段可重建全文SHA；未披露业务列的 original_row_hash 只作不透明锚。</p>
