  </el-dialog>
  <el-dialog :model-value="!!detail" title="库存完整原件核对与治理" width="min(1100px,96vw)" destroy-on-close @update:model-value="value=>{if(!value)closeDetail()}"><template v-if="detail">
   <p>{{ inventorySourceKinds[detail.source_kind] }} · {{ inventorySourceStates[detail.status] }} · {{ detail.source_record_id }}</p><p>实际SKU：{{ detail.item_kind }} #{{ detail.item_id }}；服务器登记UTC6：{{ detail.recorded_at }}；审核UTC6：{{ detail.reviewed_at??'尚未审核' }}</p><p>原专业状态：{{ detail.professional_status }}；实际原签署账户：{{ detail.signer_user_id??'未知' }}。这里不声明执照认证或运营验证。</p>
   <el-alert v-if="!detail.eligible" type="info" :closable="false" :title="detail.payload===null?'失效或终止原件的普通读取已隐去正文；仅保留技术元数据。':'原件仅供草稿审核或冻结审计，不能据此声明当前可用。'" />
   <template v-if="detail.payload"><p v-if="detail.source_kind==='inventory_observation'">原方法：{{ detail.payload.method }}；原独立实盘观察UTC6：{{ detail.payload.observed_at??'null · 技术采集没有独立实盘时刻' }}；原总量：{{ amount(detail.payload.declared_total_quantity) }}；原覆盖：{{ detail.payload.coverage }}</p><el-table v-if="detail.payload.days" :data="detail.payload.days"><el-table-column prop="date" label="原未来业务日" /><el-table-column label="原情景物理出库量"><template #default="{row}">{{ amount(row.required_quantity) }}</template></el-table-column><el-table-column prop="day_start_at" label="原日开始UTC6" width="245" /><el-table-column prop="day_end_at" label="原日结束UTC6" width="245" /></el-table><p v-if="detail.payload.orders">本完整候选共 {{ detail.payload.orders.length }} 份不可拆分采购单；原候选固定费用 {{ amount(detail.payload.plan_fixed_fee) }}；原币种 {{ detail.payload.plan_fixed_fee.currency_text??'未知' }}；原计价单位 {{ detail.payload.plan_fixed_fee.original_cost_unit_text??'未知' }}。未知不补零。</p></template>
   <p>完整原件SHA：{{ detail.content_hash }}</p><p>当前治理SHA：{{ detail.governance_hash }}</p><el-button v-if="detail.payload" @click="showOriginal=!showOriginal">{{ showOriginal?'收起院内完整库存原件':'展开院内完整库存原件' }}</el-button><pre v-if="detail.payload&&showOriginal" aria-label="院内完整库存原件">{{ JSON.stringify(detail,null,2) }}</pre>
   <template v-if="detail.can_review||detail.can_revoke"><el-form-item label="本次库存原件审核或撤销依据"><el-input v-model="basis" type="textarea" aria-label="本次库存原件审核或撤销依据" placeholder="至少20个非空白字符；撤销最多1000个Unicode字符/4000 UTF8字节" /></el-form-item><el-button v-if="detail.can_review" :disabled="!inventorySourceBasis(basis)||saving" @click="govern('publish')">审核发布库存原件</el-button><el-button v-if="detail.can_review" :disabled="!inventorySourceBasis(basis)||saving" @click="govern('reject')">审核拒绝库存原件</el-button><el-button v-if="detail.can_revoke" type="danger" :disabled="!inventoryRevokeBasis(basis)||saving" @click="govern('revoke')">撤销本条库存原件</el-button></template>
  </template></el-dialog>
  <el-dialog :model-value="unitDialog" title="实际SKU的原计数单位治理" width="min(1100px,96vw)" destroy-on-close @update:model-value="value=>unitDialog=value"><SupplySourcesPanel v-if="unitDialog&&localId" :item-kind="localKind" :item-id="localId" :active="active&&unitDialog" :governance="auditOnly" @source-changed="unitChanged" @invalidate="unitUnavailable" /></el-dialog>
 </section>
</template>
<script setup>
import {computed,defineAsyncComponent,onActivated,onDeactivated,onUnmounted,ref,watch} from 'vue';
