const props=defineProps({itemKind:{type:String,default:null},itemId:{type:Number,default:null},active:{type:Boolean,default:true},auditOnly:{type:Boolean,default:false}}),emit=defineEmits(['source-changed','invalidate','scope-change']),store=useStore();
const localKind=ref(props.itemKind),localId=ref(props.itemId),sourceKind=ref(null),keyword=ref(''),catalog=ref([]),catalogPage=ref(1),catalogTotal=ref(0),selectedName=ref(''),rows=ref([]),page=ref(1),total=ref(0),options=ref(null),loading=ref(false),saving=ref(false),error=ref(''),creating=ref(false),form=ref(null),createError=ref(''),units=ref([]),selectedUnit=ref(null),unitLoading=ref(false),raw=ref(null),rawPage=ref(1),rawLoading=ref(false),showRaw=ref(false),detail=ref(null),showOriginal=ref(false),basis=ref(''),unitDialog=ref(false);
const roles=computed(()=>store.state.user?.permissions||[]),allowed=computed(()=>!!store.state.user?.accessToken&&(props.auditOnly?roles.value.includes('super_admin'):roles.value.some(r=>['admin','director','pharmacist','super_admin'].includes(r)))),session=computed(()=>JSON.stringify([store.state.user?.accessToken,store.state.user?.username,roles.value])),scope=computed(()=>JSON.stringify([session.value,props.active,props.auditOnly,localKind.value,localId.value,sourceKind.value]));
let listVersion=0,epoch=0,detailVersion=0,formVersion=0,rawVersion=0,catalogVersion=0,live=true,destroyed=false,initialized=false;
const current=t=>t===epoch&&live&&!destroyed&&props.active&&allowed.value,clone=v=>JSON.parse(JSON.stringify(v)),amount=q=>q?.value===null?'null · '+q.absent_reason:q?.value??'未填写';
function closeCreate(){formVersion++;rawVersion++;creating.value=false;form.value=null;raw.value=null;rawPage.value=1;showRaw.value=false;rawLoading.value=false;saving.value=false;createError.value='';units.value=[];selectedUnit.value=null;}
function closeDetail(){detailVersion++;detail.value=null;showOriginal.value=false;basis.value='';saving.value=false;}
function clear(notify=true){epoch++;listVersion++;catalogVersion++;loading.value=saving.value=unitLoading.value=false;closeCreate();closeDetail();unitDialog.value=false;rows.value=[];total.value=0;catalog.value=[];catalogTotal.value=0;options.value=null;error.value='';if(notify)emit('invalidate');}
